export function validateDIGESTIVEHEPATOBILIARYSeed(): void {
  const slugs = new Set(
    DIGESTIVE_HEPATOBILIARY_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== DIGESTIVE_HEPATOBILIARY_STRUCTURES.length) {
    throw new Error(
      'Digestive system - hepatobiliary and pancreas seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    DIGESTIVE_HEPATOBILIARY_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== DIGESTIVE_HEPATOBILIARY_STRUCTURES.length) {
    throw new Error(
      'Digestive system - hepatobiliary and pancreas seed contains duplicate mesh names.',
    );
  }
  if (DIGESTIVE_HEPATOBILIARY_STRUCTURES.length !== 48) {
    throw new Error(
      'Digestive system - hepatobiliary and pancreas seed must contain exactly 48 structures.',
    );
  }
  for (const structure of DIGESTIVE_HEPATOBILIARY_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
    if (
      [
        structure.summary,
        structure.location,
        structure.function,
        structure.bloodSupply,
        structure.clinicalNotes,
      ].some((value) => value.trim().length > 0)
    ) {
      throw new Error(
        `Structure "${structure.slug}" must not contain teaching text until faculty review.`,
      );
    }
  }
}
